    temporary.write_text(str(step) + '\n')
    temporary.replace(log_dir / 'checkpoints/latest.txt')

def restore_checkpoint(actor, optimizer, path, config):
    import torch
    path = Path(path)
    state = read_json(path / 'state.json')
    prior = dict(state['config'])

